import {createPronunciation} from './pronunciation.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function youtubeId(value){try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))return null;const id=u.hostname==='youtu.be'?u.pathname.slice(1):['www.youtube.com','youtube.com','m.youtube.com'].includes(u.hostname)?u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed)\/([^/]+)/)?.[1]:null;return /^[\w-]{11}$/.test(id||'')?id:null;}catch{return null;}}
const seconds=s=>s.replace(',','.').split(':').reduce((n,x)=>n*60+Number(x),0);
export function parseCaptions(text){const cues=[];for(const block of text.replace(/\r/g,'').split(/\n\s*\n/)){const lines=block.split('\n'),i=lines.findIndex(l=>l.includes('-->'));if(i>=0){const [a,b]=lines[i].split('-->').map(s=>s.trim().split(' ')[0]);const start=seconds(a),end=seconds(b),text=lines.slice(i+1).join(' ').replace(/<[^>]*>/g,'').trim();if(Number.isFinite(start)&&Number.isFinite(end)&&end>start&&text)cues.push({start,end,text});}}if(cues.length)return cues;return text.split(/\n+/).filter(t=>t.trim()).map(t=>{const m=t.match(/^\[?(\d{1,2}:\d{2}(?::\d{2})?)\]?\s+(.+)$/);return {start:m?seconds(m[1]):null,end:null,text:m?m[2]:t.trim()};});}
let release=()=>{};
export function leaveWatch(){release();release=()=>{};}
export function watchPanel(){return `<section class="studio-paper watch-workspace"><h2>Video bilan o‘rganish</h2><p>Videoni oching. Subtitrni kuzating, gapni takrorlang va yangi iboralarni belgilang.</p><form id="watch-form"><label>YouTube havolasi<input type="url" name="url" placeholder="https://www.youtube.com/watch?v=…"></label><p>yoki <label class="btn">Qurilmadan video<input id="watch-file" type="file" accept="video/*"></label></p><details><summary>Subtitr qo‘shish</summary><label>VTT yoki SRT fayl<input id="watch-captions" type="file" accept=".vtt,.srt,.txt"></label><label>Subtitr matni<textarea name="transcript" rows="5" maxlength="50000" placeholder="00:05 This is the first sentence.&#10;00:09 This is the next sentence."></textarea></label><p>Vaqt belgilari bilan gapni bosib videoning shu joyiga o‘tasiz. Subtitr avtomatik olinmaydi.</p></details><button class="btn primary">Videoni ochish</button></form><p id="watch-error" role="alert"></p><div id="watch-lesson"></div></section>`;}
export function mountWatch(account){leaveWatch();const $=s=>document.querySelector(s),key='lexora.watch.'+(account||'guest'),form=$('#watch-form');let blob='',localFile=null,cues=[],selected=0,loop=false,iframe=null,video=null,savedWords=[];
const explanations=new Map();let explainId=0;
const audio=createPronunciation({getPreferences:()=>({accent:'en-GB',rate:.9}),onError:m=>$('#watch-error').textContent=m});
const command=(func,args=[])=>iframe?.contentWindow?.postMessage(JSON.stringify({event:'command',func,args}),'https://www.youtube-nocookie.com');
const jump=i=>{selected=i;const cue=cues[i];if(cue?.start!==null){if(video)video.currentTime=cue.start;else command('seekTo',[cue.start,true]);}document.querySelectorAll('.watch-cue').forEach((r,j)=>r.classList.toggle('current',i===j));};
const show=data=>{audio.stop();if(blob)URL.revokeObjectURL(blob);blob=localFile?URL.createObjectURL(localFile):'';cues=parseCaptions(data.transcript||'');$('#watch-lesson').innerHTML=`<div class="watch-layout"><section><div id="watch-player">${blob?`<video id="watch-video" class="watch-frame" controls playsinline src="${blob}"></video>`:`<iframe id="watch-youtube" class="watch-frame" title="Mashq videosi" referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube-nocookie.com/embed/${data.id}?enablejsapi=1&playsinline=1&rel=0&origin=${encodeURIComponent(location.origin)}" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`}</div><div class="buttons"><button class="btn" type="button" id="watch-prev">Oldingi gap</button><button class="btn" type="button" id="watch-loop" aria-pressed="false">Gapni takrorlash</button><button class="btn" type="button" id="watch-next">Keyingi gap</button><label>Tezlik<select id="watch-rate">${[.5,.75,1,1.25,1.5].map(x=>`<option ${x===1?'selected':''}>${x}</option>`).join('')}</select></label></div>${blob?'':`<a class="text-btn" href="https://www.youtube.com/watch?v=${data.id}" target="_blank" rel="noopener">Video ochilmasa YouTube’da ko‘rish</a>`}<div id="watch-word" class="notice" aria-live="polite">Ma’nosini ko‘rish yoki talaffuzini eshitish uchun so‘zni bosing.</div><h3>Belgilangan iboralar</h3><div id="watch-saved"></div></section><section class="watch-lines" aria-label="Video subtitrlari">${cues.length?cues.map((cue,i)=>`<div class="watch-cue"><button type="button" class="text-btn" data-cue="${i}">${cue.start===null?'Gap '+(i+1):Math.floor(cue.start/60)+':'+String(Math.floor(cue.start%60)).padStart(2,'0')}</button><p>${cue.text.split(/(\s+)/).map(word=>/^\s+$/.test(word)?word:`<button type="button" class="caption-word" data-word="${e(word)}">${e(word)}</button>`).join('')}</p><button type="button" class="text-btn" data-sentence="${i}">Gapni tinglash</button></div>`).join(''):'<p>Video tayyor. Matn bilan ishlash uchun yuqoridan subtitr fayli yoki matn qo‘shing.</p>'}</section></div>`;video=$('#watch-video');iframe=$('#watch-youtube');if(video){video.onerror=()=>$('#watch-error').textContent='Video formati qurilmada ochilmadi. MP4 (H.264) formatini tanlang.';video.ontimeupdate=()=>{const cue=cues[selected];if(loop&&cue?.end&&video.currentTime>=cue.end)video.currentTime=cue.start;};}$('#watch-rate').onchange=ev=>{if(video)video.playbackRate=Number(ev.target.value);else command('setPlaybackRate',[Number(ev.target.value)]);};$('#watch-prev').onclick=()=>jump(Math.max(0,selected-1));$('#watch-next').onclick=()=>jump(Math.min(cues.length-1,selected+1));$('#watch-loop').onclick=ev=>{loop=!loop;ev.target.setAttribute('aria-pressed',String(loop));if(!video&&loop)$('#watch-error').textContent='YouTube’da gapni qaytarish uchun vaqt tugmasini bosing. Avtomatik loop qurilmadan ochilgan videoda ishlaydi.';};document.querySelectorAll('[data-cue]').forEach(b=>b.onclick=()=>jump(Number(b.dataset.cue)));document.querySelectorAll('[data-sentence]').forEach(b=>b.onclick=()=>audio.speak(cues[Number(b.dataset.sentence)].text));document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{const word=b.dataset.word.replace(/^[^a-z]+|[^a-z]+$/gi,'');if(!word)return;$('#watch-word').innerHTML=`<b>${e(word)}</b><div id="watch-meaning" role="status">Kontekstdagi ma’nosi yuklanmoqda…</div><div class="buttons"><button class="btn" type="button" id="watch-pronounce">Talaffuz</button><button class="btn" type="button" id="watch-save-word">Belgilash</button><a class="btn" href="https://translate.google.com/?sl=en&tl=uz&text=${encodeURIComponent(word)}&op=translate" target="_blank" rel="noopener">Tarjima</a><a class="btn" href="https://youglish.com/pronounce/${encodeURIComponent(word)}/english" target="_blank" rel="noopener">Boshqa kontekst</a></div>`;const requestId=++explainId,context=b.closest('.watch-cue')?.querySelector('p')?.textContent||word,cacheKey=word+'|'+context;const showMeaning=data=>{if(requestId!==explainId||!$('#watch-meaning'))return;$('#watch-meaning').innerHTML='<p><b>'+e(data.translation)+'</b></p><p>'+e(data.explanation)+'</p><p>'+e(data.example)+'</p><small>Avtomatik izoh · ma’noni gap bilan solishtiring.</small>';};if(explanations.has(cacheKey))showMeaning(explanations.get(cacheKey));else fetch('/api/classroom/watch/explain',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({word,context})}).then(async r=>{const data=await r.json();if(!r.ok)throw Error(data.error||'Izoh yuklanmadi.');explanations.set(cacheKey,data);showMeaning(data);}).catch(er=>{if(requestId===explainId&&$('#watch-meaning'))$('#watch-meaning').textContent=er.message;});$('#watch-pronounce').onclick=()=>audio.speak(word);$('#watch-save-word').onclick=()=>{if(!savedWords.includes(word))savedWords.push(word);try{localStorage.setItem(key+'.words',JSON.stringify(savedWords));}catch{}drawSaved();};});drawSaved();};
const drawSaved=()=>{const el=$('#watch-saved');if(el)el.textContent=savedWords.join(' · ')||'Hali ibora belgilanmagan.';};
try{savedWords=JSON.parse(localStorage.getItem(key+'.words')||'[]');const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&youtubeId(saved.url)){form.elements.url.value=saved.url;form.elements.transcript.value=saved.transcript||'';show({...saved,id:youtubeId(saved.url)});}}catch{}
$('#watch-file').onchange=ev=>{localFile=ev.target.files[0]||null;};$('#watch-captions').onchange=async ev=>{const f=ev.target.files[0];if(f){if(f.size>200000){$('#watch-error').textContent='Subtitr 200 KB dan kichik bo‘lsin.';return;}form.elements.transcript.value=await f.text();}};
form.onsubmit=ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(form)),id=youtubeId(data.url);if(!localFile&&!id){$('#watch-error').textContent='YouTube havolasini yoki video faylni tanlang.';return;}$('#watch-error').textContent='';if(!localFile)try{localStorage.setItem(key,JSON.stringify(data));}catch{}show({...data,id});};release=()=>{explainId++;audio.stop();if(video)video.pause();if(blob)URL.revokeObjectURL(blob);};}
